class StackedSquare {
	constructor(x, y, s, num, pal) {
		this.x = x;
		this.y = y;
		this.s = s;
		this.num = num;
		this.pal = pal;

		this.genStates();

		// console.log(this)
	}

	genStates() {
		// gen stacked squre states: size, color, angle
		this.states = [];
		const startAng = random(-0.1, 0.1);
		const deviAng = random(0.1, 0.2) * Math.sign(random(-1, 1));
		let lastClr = "notacolor";

		for (let i = 0; i < this.num; i++) {
			const ang = startAng + i * deviAng + random(-0.1, 0.1);
			let clr = random(this.pal), tries = 10;
			let _wG_1 = 0; while ((clr == lastClr && tries--) && ++_wG_1 < 20000) {
				clr = random(this.pal);	
			}
			lastClr = clr;

			this.states.push({
				sze: map(i, 0, this.num, this.s, 0),
				clr,
				ang
			});
		}
	}

	show() {
		push();
		rectMode(CENTER);
		noStroke();
		// translate(this.x, this.y);

		for (const st of this.states) {
			push();
			fill(st.clr);

			// gradient?
			if (true) {
				const ctx = drawingContext;
				const bbox = {x1: this.x-st.sze/2, y1: this.y-st.sze/2, x2: this.x+st.sze/2, y2: this.y+st.sze/2}; // this.getBoundingBox(pts);
				const gradient = ctx.createLinearGradient(bbox.x1, bbox.y1, bbox.x2, bbox.y2);
				const clrChoosen = adjColorBrightness(st.clr, 1);
				const clrLighten = adjColorBrightness(clrChoosen, 1.5);
				const clrDarken = adjColorBrightness(clrChoosen, 0.5);

				gradient.addColorStop(0, clrLighten);
				gradient.addColorStop(0.5, clrChoosen);
				gradient.addColorStop(1, clrDarken);
				ctx.fillStyle = gradient;
			}

			const dx = cos(st.ang) * st.sze / 2;
			const dy = sin(st.ang) * st.sze / 2;
			const rad = sqrt(2*st.sze*st.sze) / 2;
			beginShape();
			for (let a = QUARTER_PI; a < TWO_PI; a += (Math.max(0.001, Math.abs(HALF_PI)) || 1)) {
				const xx = cos(a+st.ang) * rad;
				const yy = sin(a+st.ang) * rad;
				vertex(this.x + xx, this.y + yy);
			}
			endShape();

			push();
			const strClr = FG; // strClr.setAlpha(128);
			stroke(strClr); strokeWeight(2); noFill();
			translate(this.x, this.y);
			rotate(st.ang + random(-0.1, 0.1));
			rect(0, 0, st.sze);
			pop();

			pop();
		}

		pop();
	}
}

