const NUM_SQUARES = 17;
let pal, BG, FG, squares, status;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of randomly stacked squares with slightly changing rotation and different colors from a palette till number of 17 squares are reached with one empty spot or different palette.");
	pixelDensity(1);
	frameRate(30);

	pal = [...random(palettes)]; // pick random palette
	BG = pal.splice(~~random(pal.length), 1)[0]; // extract random bg color
	BG = adjColorSaturation(BG, 0.5); // desaturate 
	FG = adjColorBrightness(BG, 0.5);

	initRectangles();

	status = {
		startFrame: frameCount ? frameCount : 1,
		doStripes: false,
		finished: false,
		ys: Array(height),
	}

	loop();
	// console.log(status)
}

function draw() {
	if (!status.doStripes) {
		// 1st frame
		background(BG);

		for (let sq of squares) {
			sq.show();
		}

		// blurring not working well
		noLoop();
		return; 

		status.doStripes = true;

	} else {
		// do stripes till end
		const yLine = ~~(randomGaussian(0, 100) + height) % height; // ~~random(height);
		status.ys[yLine] = true;
		blurLineXY(~~(width/3), yLine); // blurLine(yLine);

		let linesProcessed = 0;
		for (const yL of status.ys) if (yL) linesProcessed++
		if (linesProcessed == height/2) status.finished = true;
	}

	// end on end ^^	
	if (status.finished) noLoop();
}

function blurLineXY(x, y) {
	console.log(`blurLineXY(${x}, ${y})`)
	const px = color(get(x, y));

	strokeWeight(1);
