	for (let xx = 0; xx <= x; xx++) {
		const f = xx/x;
		stroke(lerpColor(BG, px, f));
		circle(xx, y, 2);
	}
}


function blurLine(y) {
	console.log(`blurLine(${y})`)
	function isSameClr(c1, c2) {
		return c1.r == c2.r && c1.g == c2.g && c1.b == c2.b;
	}
	const bgO = {r: red(window.color(BG)), g: green(window.color(BG)), b: blue(window.color(BG))};	
	const fgO = {r: red(window.color(FG)), g: green(window.color(FG)), b: blue(window.color(FG))};

	loadPixels();
	// find segments (for now only 1st one)
	let segs = [], modeBG = true, xs = 0, xe = width;

