	for (let x = 0; x < width; x++) {
		const pxO = {
			r: pixels[idx],
			g: pixels[idx + 1],
			b: pixels[idx + 2]
		}
		idx += 4;

		const pxIsBg = isSameClr(pxO, bgO);
		const pxIsFg = isSameClr(pxO, fgO);
		const pxIsFBg = pxIsBg || pxIsFg;
		/*
		console.log(`${x}: pxIsBg ${pxIsBg} pxIsFg ${pxIsFg}`)
		console.log(`bgO: ${bgO.r} ${bgO.g} ${bgO.b}`)
		console.log(`pxO: ${pxO.r} ${pxO.g} ${pxO.b}`)
		*/
		if (x === 0 && !pxIsFBg) {
			modeBG = false; // line not started with background
			console.log("starts bg")
		}

		if (modeBG) { 
			// searching for first non bg pixel
			if (!pxIsFBg) {
				segs.push({x1: xs, x2: x});
				console.log(`segment found ${xs} ${x}`, segs);
				modeBG = false;
			}
		} else {
