}

function initRectangles(num = NUM_SQUARES) {
	const minNum = 2;
	const sze = ~~(max(width, height) / minNum * 0.9);
	let numX = ~~min(width / sze, num / (minNum + 0.7))
	let numY = ~~min(height / sze, num / (minNum + 0.7))

	// add squares
	squares = [];
	for (let j = 0; j < numY; j++) {
		for (let i = 0; i < numX; i++) {
			const x = i * sze + (width - numX * sze + sze) / 2;
			const y = j * sze + (height - numY * sze + sze) / 2;
			const s = sze * random(0.75, 0.85); // deviate size a bit
			const newSquare = new StackedSquare(x + random(-s / 8, s / 8), y + random(-s / 8, s / 8), s, 1, pal);
			squares.push(newSquare);
		}
	}

	// delete random spot(s)
	shuffle(squares, true);
	if (random() < 0.5) { // either delete some spot(s)
		if (random() < 0.9) squares.splice(0, 1);
		if (random() < 0.5 && squares.length > NUM_SQUARES * 0.4) squares.splice(0, 1);
	} else { // or use another palette for one spot
		squares[0].pal = random(palettes);
	}

	// add stacking for sum = num squares
	let sumSquares = squares.length;
	for (let i = 0; i < 1000; i++) {
		if (random() < 0.1) {
			squares[i % squares.length].num++;
			sumSquares++;
			if (sumSquares >= num) break;
		}
	}

	// recalc inner stacks
	for (let sq of squares) {
		sq.genStates();
	}
}

